import cv2,numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1].astype(float)
for cx,cy,r in [(54.7,51.0,7.5),(109.5,36.0,5.0)]:
 print('\\nball',cx,cy,r)
 # print luminance and chroma values inside rows, to determine shading center
 for y in range(int(cy-r),int(cy+r)+1):
  if y<0 or y>=144:continue
  vals=[]
  for x in range(int(cx-r),int(cx+r)+1):
   if x<0 or x>=256:continue
   dx=(x-cx)/r;dy=(y-cy)/r
   if dx*dx+dy*dy<1:
    vals.append('%3d'%round(im[y,x,0]))
  if vals:print('%2d'%y,' '.join(vals))
PY"

